import sys

def longestSubstring(N: int, S: str) -> str:
    if N < 2:
        return "-1"

    best_len = 0
    best_sub = ""

    for i in range(N):
        for j in range(i + 1, N):
            k = 0
            while i + k < j and j + k < N and S[i + k] == S[j + k]:
                k += 1

            if k > best_len:
                best_len = k
                best_sub = S[i:i + k]
            elif k == best_len and best_sub != S[i:i + k]:
                if i < S.find(best_sub):
                    best_sub = S[i:i + k]

    return best_sub if best_len > 0 else "-1"

def main():
    lines = sys.stdin.read().strip().splitlines()
    if not lines:
        return
    try:
        N = int(lines[0].strip())
        S = lines[1].strip() if len(lines) > 1 else ""
    except ValueError:
        return

    result = longestSubstring(N, S)
    print(result)

if __name__ == "__main__":
    main()
